const (
	ConfigKeyMihomoConfigs  = "mihomo_configs"
	ConfigKeySingBoxConfigs = "singbox_configs"
)

// InitDefaultSubscriptionConfigs 初始化默认订阅配置
func InitDefaultSubscriptionConfigs() error {
	// 检查是否已有 Mihomo 配置
	mihomoConfig, _ := GetSystemConfig(ConfigKeyMihomoConfigs)
	if mihomoConfig == "" || mihomoConfig == "[]" {
		if err := SetSystemConfig(ConfigKeyMihomoConfigs, defaultMihomoConfig, "Mihomo 订阅配置模板"); err != nil {
			return err
		}
		log.Println("已初始化默认 Mihomo 订阅配置")
	}

	// 检查是否已有 SingBox 配置
	singboxConfig, _ := GetSystemConfig(ConfigKeySingBoxConfigs)
	if singboxConfig == "" || singboxConfig == "[]" {
		if err := SetSystemConfig(ConfigKeySingBoxConfigs, defaultSingBoxConfig, "SingBox 订阅配置模板"); err != nil {
			return err
		}
		log.Println("已初始化默认 SingBox 订阅配置")
	}

	return nil
}

